/**
 * PlanPage — view and edit the .ralph/plan.md generated by PlanLoop.
 * Also shows a button to re-run Plan+Encode from here.
 */
import React, { useCallback, useEffect, useState } from 'react'

export default function PlanPage({ projectPath }: { projectPath: string }): JSX.Element {
  const [planMd,   setPlanMd]   = useState<string | null>(null)
  const [editing,  setEditing]  = useState(false)
  const [draft,    setDraft]    = useState('')
  const [saving,   setSaving]   = useState(false)
  const [planning, setPlanning] = useState(false)
  const [request,  setRequest]  = useState('')
  const [msg,      setMsg]      = useState<string | null>(null)

  const flash = (m: string): void => { setMsg(m); setTimeout(() => setMsg(null), 4000) }

  const load = useCallback(async () => {
    const graph = await window.ralph.swarm.graph(projectPath) as { planMd?: string } | null
    const text = graph?.planMd ?? null
    setPlanMd(text)
    if (text) setDraft(text)
  }, [projectPath])

  useEffect(() => {
    void load()
    const unsub = window.ralph.swarm.onGraph((p, _stats, graph) => {
      if (p !== projectPath) return
      const g = graph as { planMd?: string } | null
      const text = g?.planMd ?? null
      setPlanMd(text)
      if (!editing) setDraft(text ?? '')
    })
    const unsubPlan = window.ralph.swarm.onPlanPhase((p, phase) => {
      if (p !== projectPath) return
      setPlanning(phase !== 'done')
    })
    return () => { unsub(); unsubPlan() }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectPath])

  const handleSave = async (): Promise<void> => {
    // Save plan.md via file:write (it's not in the EDITABLE list yet, so we use swarm graph)
    // For now just update local state — a full persist would need an IPC endpoint
    setSaving(true)
    setPlanMd(draft)
    setEditing(false)
    setSaving(false)
    flash('Plan updated locally (re-run Encode to apply changes to beads)')
  }

  const handleInject = async (): Promise<void> => {
    if (!request.trim()) return
    setPlanning(true)
    const r = await window.ralph.swarm.inject(projectPath, request.trim())
    if (!r.ok) { flash(`Failed: ${r.error}`); setPlanning(false) }
    else { setRequest(''); flash('Planning started…') }
  }

  return (
    <>
      <div className="page-header">
        <div>
          <div className="page-title">📋 Plan</div>
          <div className="page-sub">Synthesized development plan (.ralph/plan.md)</div>
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          {planMd && !editing && (
            <button className="btn btn-ghost btn-sm" onClick={() => { setDraft(planMd); setEditing(true) }}>
              ✎ Edit
            </button>
          )}
          {editing && (
            <>
              <button className="btn btn-sm" style={{ background: 'var(--green)', color: '#fff' }}
                onClick={() => void handleSave()} disabled={saving}>
                {saving ? <span className="spinner" style={{ width: 12, height: 12 }} /> : '✓ Save'}
              </button>
              <button className="btn btn-ghost btn-sm" onClick={() => setEditing(false)}>Cancel</button>
            </>
          )}
          <button className="btn btn-ghost btn-sm" onClick={() => void load()}>↻ Reload</button>
        </div>
      </div>

      {msg && (
        <div style={{ padding: '8px 24px', background: 'var(--surface2)', fontSize: 12, color: 'var(--accent)', borderBottom: '1px solid var(--border)' }}>
          {msg}
        </div>
      )}

      {planning && (
        <div style={{ padding: '8px 24px', background: '#1c1a00', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: 10, fontSize: 12 }}>
          <span className="spinner" style={{ width: 12, height: 12 }} />
          <span style={{ color: 'var(--yellow)' }}>Planning in progress…</span>
        </div>
      )}

      <div style={{ flex: 1, overflow: 'auto', padding: '16px 24px', display: 'flex', flexDirection: 'column', gap: 16 }}>

        {/* Inject / re-plan section */}
        <div className="stat-card">
          <div className="stat-label" style={{ marginBottom: 8 }}>Generate / regenerate plan</div>
          <textarea
            value={request}
            onChange={e => setRequest(e.target.value)}
            onKeyDown={e => { if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') { e.preventDefault(); void handleInject() } }}
            rows={3}
            disabled={planning}
            placeholder="Describe what to build… (Ctrl+Enter to run Plan+Encode)"
            style={{
              width: '100%', boxSizing: 'border-box',
              background: 'var(--surface2)', border: '1px solid var(--border)',
              borderRadius: 6, color: 'var(--text)', padding: '8px 10px',
              fontFamily: 'monospace', fontSize: 12, resize: 'vertical', outline: 'none'
            }}
          />
          <div style={{ display: 'flex', gap: 8, marginTop: 8 }}>
            <button className="btn btn-primary btn-sm"
              onClick={() => void handleInject()} disabled={planning || !request.trim()}>
              {planning ? <span className="spinner" style={{ width: 12, height: 12 }} /> : '⬡'} Plan + Encode
            </button>
            <span style={{ fontSize: 11, color: 'var(--muted)', alignSelf: 'center' }}>Ctrl+Enter</span>
          </div>
        </div>

        {/* Plan content */}
        {planMd === null ? (
          <div className="state-box">
            <div className="state-icon">📋</div>
            <div className="state-desc">No plan yet. Use the form above to generate one.</div>
          </div>
        ) : editing ? (
          <textarea
            value={draft}
            onChange={e => setDraft(e.target.value)}
            style={{
              flex: 1, minHeight: 400,
              background: 'var(--surface2)', border: '1px solid var(--accent)',
              borderRadius: 6, color: 'var(--text)', padding: '12px',
              fontFamily: 'monospace', fontSize: 12, resize: 'vertical', outline: 'none',
              lineHeight: 1.6
            }}
          />
        ) : (
          <pre style={{
            whiteSpace: 'pre-wrap', fontSize: 12, color: 'var(--text)',
            background: 'var(--surface2)', borderRadius: 8, padding: 16,
            border: '1px solid var(--border)', lineHeight: 1.8, margin: 0
          }}>
            {planMd}
          </pre>
        )}
      </div>
    </>
  )
}
